-- 00064_film_starter_clips.sql
-- The first film clips for the Film tab (docs/plans/film-and-plays.md, F4).
--
-- 39 teaching videos from official coaching and league channels, 3 to 6 for
-- each of the 8 themes. Each one was checked on 14 Nov 2026: YouTube oEmbed
-- answers (embedding allowed), it is marked family-safe and plays in Ireland.
-- Jr. NBA videos were left out because they are likely Made for Kids
-- (YouTube Developer Policies III.E.4.j). The title and channel are copied
-- from YouTube. Each clip is the whole video (up to 10 minutes) and asks its
-- two questions at the end, because nobody has picked exact moments yet: the
-- owner can change any clip, its start and end, and its questions, or
-- unpublish it, in Owner tools.
--
-- Every clip is free (YouTube does not allow charging to watch embedded
-- video) and published. A clip is only added when its video is not in the
-- library already, so this is safe to run again and never overwrites an edit
-- made in Owner tools.
--
-- The two starter packs from 00062 get their clips and are published: Start
-- here takes the spacing and help defence clips, Reading the pick-and-roll
-- takes the pick-and-roll clips.

INSERT INTO public.film_clips (youtube_video_id, start_s, end_s, title, channel_name, theme, level, questions, is_free, published_at)
SELECT v.youtube_video_id, v.start_s, v.end_s, v.title, v.channel_name, v.theme, v.level, v.questions, true, now()
FROM (VALUES
  ($q$GNk9tw7v1jw$q$, 0, 316, $q$Activate Corner Spacing: Conceptual Basketball Offense Explained$q$, $q$Basketball Immersion$q$, $q$spacing$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"The ball swings to you in the corner. Your defender is right on you and there is no lane. What do you do?","options":["Hold the ball and wait","Force up a shot anyway","Move the ball or cut to keep the play going"],"correct_index":2,"explanation":"If there is no shot or drive, standing still kills the play. Keep it moving so the defence has to react again.","moment_s":316},{"key":"q2","question":"Why do good teams keep a player in the corner at all?","options":["It is the easiest place to defend","It pulls a defender away from the paint","Corner players never get the ball"],"correct_index":1,"explanation":"A player in the corner drags their defender wide, which leaves more room in the middle for drives.","moment_s":316}]$q$::jsonb),
  ($q$oz2LXAxfmCE$q$, 0, 273, $q$Fixing Offensive Basketball Spacing Without Changing Your Offense$q$, $q$PGC Coaching$q$, $q$spacing$q$, $q$beginner$q$, $q$[{"key":"q1","question":"Two of your teammates are standing about two metres apart. What should one of them do?","options":["Move away to the next open spot","Stay where they are","Run over and ask for the ball"],"correct_index":0,"explanation":"Two attackers close together let one defender guard both. Spread out so each defender has to choose.","moment_s":273},{"key":"q2","question":"A teammate drives to the basket. What does good spacing give them?","options":["More defenders to beat","Nothing, spacing only matters for shooters","Room to get to the rim or kick it out"],"correct_index":2,"explanation":"When everyone is spread out, help defenders are far away, so the driver has space to score or pass.","moment_s":273}]$q$::jsonb),
  ($q$6tb3W3T-s3s$q$, 0, 511, $q$The Gap Theory (Spacing)$q$, $q$The Film Room$q$, $q$spacing$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"What is a 'gap' in the defence?","options":["The time between two passes","The space between two defenders you can drive into","The space under the basket"],"correct_index":1,"explanation":"A gap is the room between two defenders. Good spacing makes those gaps bigger so drives get through.","moment_s":511},{"key":"q2","question":"Why does bad spacing make it harder to drive?","options":["One defender can guard the driver and their teammate at once","The referee calls more fouls","The ball is harder to dribble"],"correct_index":0,"explanation":"When attackers bunch up, defenders can help without leaving anyone open. Spread out and they cannot.","moment_s":511}]$q$::jsonb),
  ($q$osY0NWe4M0w$q$, 0, 600, $q$Elite Spacing Isn't Just About Outside Shooting$q$, $q$NBA$q$, $q$spacing$q$, $q$advanced$q$, $q$[{"key":"q1","question":"Every player is spread out and your defender is looking at the ball. What is a smart move?","options":["Cut to the basket behind them","Stand still and wait","Walk to the ball and ask for it"],"correct_index":0,"explanation":"A defender watching the ball has lost you. Cutting behind them is one of the easiest ways to score.","moment_s":600},{"key":"q2","question":"After you cut and do not get the ball, what next?","options":["Stay under the basket","Stand next to a teammate","Fill an empty spot on the outside"],"correct_index":2,"explanation":"If the cut does not work, refill an empty spot so the spacing stays good for the next player.","moment_s":600}]$q$::jsonb),
  ($q$Ry5tcG-2ZBU$q$, 0, 499, $q$Basketball IQ Test #5 - Who's the Help Defender?$q$, $q$The Film Room$q$, $q$help_defence$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"A driver gets into the paint and a new defender steps up to stop them. Who is open?","options":["The driver","The player that helper just left","Nobody"],"correct_index":1,"explanation":"Help leaves someone. Find who stepped up, then pass to the player they were guarding.","moment_s":499},{"key":"q2","question":"Why is it useful for an attacker to know who the help defender is?","options":["It tells you where the open pass will be","So you can avoid passing","It does not matter on offence"],"correct_index":0,"explanation":"Making two defenders guard one player means someone is free. Spotting the helper tells you who.","moment_s":499}]$q$::jsonb),
  ($q$JjLW3wrJXHg$q$, 0, 478, $q$Detailed Breakdown of Pack Line Defense$q$, $q$The Film Room$q$, $q$help_defence$q$, $q$advanced$q$, $q$[{"key":"q1","question":"In the Pack Line, where do defenders away from the ball stand?","options":["Touching their player out wide","Under the basket","Inside an imaginary line about a step inside the three-point line"],"correct_index":2,"explanation":"Packing in keeps the gaps closed, so drivers run into help.","moment_s":478},{"key":"q2","question":"The ball is kicked out to a shooter after you helped. What do you do?","options":["Let them shoot, it is too late","Close out to them under control","Stay in the paint"],"correct_index":1,"explanation":"Packing in only works if you then get back out to the shooter, under control.","moment_s":478}]$q$::jsonb),
  ($q$G3WkZLavHSA$q$, 0, 168, $q$The Right Way to Closeout & Contest$q$, $q$Hooper University$q$, $q$closeouts$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"Why do coaches now teach sprinting most of the way on a closeout?","options":["Because walking is against the rules","So you get there in time to bother the shot","So you can fly past the shooter"],"correct_index":1,"explanation":"Top shooters need very little time. Sprinting gets you there, then you stop with balance.","moment_s":168},{"key":"q2","question":"You flew past the shooter and they drove by you. What went wrong?","options":["You did not stop under control before you arrived","The shooter was just lucky","You should never close out"],"correct_index":0,"explanation":"Arriving too fast and off balance gives the shooter an easy drive. Stop on balance first.","moment_s":168}]$q$::jsonb),
  ($q$ovS7JZcdIno$q$, 0, 600, $q$How to Play Modern Defense | Step 1 | Sprint Stop Closeout$q$, $q$PGC Basketball - Point Guard College$q$, $q$closeouts$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"A shooter catches the ball and your defender is in help. What does the defender do first?","options":["Walk out slowly","Stay in the paint","Sprint towards the shooter"],"correct_index":2,"explanation":"Good shooters punish a slow closeout. Get there fast.","moment_s":600},{"key":"q2","question":"What makes a closeout good at the end?","options":["Turning your back to the shooter","A balanced stop with a hand up, ready to slide","Jumping at the shooter"],"correct_index":1,"explanation":"You want to bother the shot without giving up a drive, so finish balanced with a hand up.","moment_s":600}]$q$::jsonb),
  ($q$Qdq2yEoTEAw$q$, 0, 483, $q$The Gap Theory (Driving Bad Closeouts)$q$, $q$The Film Room$q$, $q$closeouts$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"A defender sprints at you and is still moving fast as you catch. What is the read?","options":["Drive past them","Pass back to the top","Hold the ball"],"correct_index":0,"explanation":"A defender flying at you cannot change direction. One dribble past them gets you into the gap.","moment_s":483},{"key":"q2","question":"A defender closes out short and stays back. What is open?","options":["A drive into a crowd","Nothing","The shot"],"correct_index":2,"explanation":"If they stop too far away, they cannot bother your shot. Shoot it if you are in range.","moment_s":483}]$q$::jsonb),
  ($q$96o3crO53NY$q$, 0, 65, $q$Attacking a Defensive Closeout Using a Stab Dribble$q$, $q$Basketball Immersion$q$, $q$closeouts$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"Why get the ball on the floor fast against a closeout?","options":["To waste time","To go past the defender before they get set","To show off"],"correct_index":1,"explanation":"The defender is still moving and off balance. Attack straight away, before they recover.","moment_s":65},{"key":"q2","question":"What should the defender have done to stop this?","options":["Arrive under control, ready to slide","Run faster at the shooter","Jump to block the shot"],"correct_index":0,"explanation":"A balanced closeout takes away the quick drive. A wild one gives it away.","moment_s":65}]$q$::jsonb),
