  ($q$B-ouIZ0NDJ0$q$, 0, 491, $q$Basketball IQ Test #4 - How to Read Ballscreen Coverages$q$, $q$The Film Room$q$, $q$pick_and_roll$q$, $q$intermediate$q$, $q$[{"key":"q1","question":"You come off a screen and the big defender stays back near the basket. What is usually open?","options":["A pull-up shot","A lob","Nothing"],"correct_index":0,"explanation":"When the big drops back, there is space in front of them for a mid-range or three.","moment_s":491},{"key":"q2","question":"You come off a screen and two defenders jump at you. What is the read?","options":["Dribble through both of them","Pick the ball up and hold it","Pass quickly to the screener or an open teammate"],"correct_index":2,"explanation":"Two defenders on you means someone is open. Get it out fast.","moment_s":491}]$q$::jsonb),
