) AS v(youtube_video_id, start_s, end_s, title, channel_name, theme, level, questions)
WHERE NOT EXISTS (SELECT 1 FROM public.film_clips c WHERE c.youtube_video_id = v.youtube_video_id);

-- Fill the starter packs, in library order, keeping anything already in them
INSERT INTO public.film_pack_clips (pack_id, clip_id, position)
SELECT p.id, c.id, (row_number() OVER (PARTITION BY p.id ORDER BY c.theme DESC, c.level, c.title))::int - 1
FROM public.film_packs p
JOIN public.film_clips c
  ON (p.slug = 'start-here-spacing-and-help' AND c.theme IN ('spacing', 'help_defence'))
  OR (p.slug = 'reading-the-pick-and-roll' AND c.theme = 'pick_and_roll')
WHERE p.owner_id IS NULL
  AND c.published_at IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM public.film_pack_clips x WHERE x.pack_id = p.id)
ON CONFLICT (pack_id, clip_id) DO NOTHING;

UPDATE public.film_packs
SET published_at = now()
WHERE owner_id IS NULL
  AND slug IN ('start-here-spacing-and-help', 'reading-the-pick-and-roll')
  AND published_at IS NULL;
